-- ═══════════════════════════════════════════════════════════════
-- 0065: GST rates, taken from the OFFICIAL rate schedule.
--
-- Source: Notification No. 9/2025-Central Tax (Rate) dated 17-9-2025
-- (as corrected by corrigendum 18-9-2025), in force from 22-9-2025, which
-- supersedes Notification 1/2017-CT(R). Schedule I = 2.5% CGST (5% GST),
-- Schedule II = 9% CGST (18% GST).
--
-- THIS CORRECTS 0064. That file put LED lighting and water pumps at 5% on the
-- strength of secondary commentary; the notification itself says otherwise:
--
--   Sch II entry 614  9405  "Luminaires and lighting fittings ... having a
--                            permanently fixed light source"          -> 18%
--   Sch II entry 511  8539  "Electrical filament or discharge lamps"  -> 18%
--   Sch II entry 486  8513  Portable electric lamps (torches)         -> 18%
--   Sch II entry 400  8413  "Power driven pumps primarily designed for
--                            handling water ... submersible ..."      -> 18%
--   Sch II entries 401/508/509/510/516  fans, switchgear, boards,
--                            parts, wire & cable                      -> 18%
--
-- There is NO LED entry in Schedule I. The only 5% entries that touch this
-- catalogue are:
--   Sch I entry 437(f)  "Solar lantern / solar lamp" (renewable energy
--                        devices, Ch 84/85/94)                        -> 5%
--   Sch I entry 438     8504 "Charger or charging station for
--                        Electrically operated vehicles"              -> 5%
--
-- Net effect: everything is 18% except 5 solar lamps and 5 EV chargers.
-- Run this even if 0064 was already applied; it is a full, idempotent reset.
-- ═══════════════════════════════════════════════════════════════


-- 5% (10 products)
update public.products set gst_rate = 0.0500 where id in ('hav-ehmvd007aa','hav-ehmvd011aa','hav-ehmvd022aa','hav-ehmvo007cc','hav-ehmvo007dd','hav-lhextdpgtn1k010','hav-lhextepwfn1r003','hav-lhextip7cn1m010','hav-lhextip7tn1b010','hav-lhextop7cn1r006');

