-- Anything still on the old 5% (e.g. a product added between migrations)
-- that is not a solar lamp or an EV charger:
select id, name, category, gst_rate from public.products
where is_active and gst_rate < 0.18
order by category, name;

select (gst_rate*100)::text || '%' as rate, count(*) as products
from public.products where is_active group by 1 order by 2 desc;

